/* Public-cohort starting points. No invented GPA/essay coefficients or major-rate substitution. */
var AdmissionsEstimator=(()=>{
 const college=s=>({'University of Washington Seattle':'UW Seattle','University of Washington Bothell':'UW Bothell','University of Washington Tacoma':'UW Tacoma'}[s]||s);
 function wilson(k,n){if(!Number.isInteger(n)||n<1||k<0||k>n)return null;const z=1.95996398454,p=k/n,d=1+z*z/n,m=(p+z*z/(2*n))/d,h=z*Math.sqrt(p*(1-p)/n+z*z/(4*n*n))/d;return[Math.max(0,m-h),Math.min(1,m+h)]}
 function evidence(record){if(!record)return null;const v=record.value,n=typeof v==='object'?(v.applicants??v.eligibleApplicants):null,k=typeof v==='object'?v.admitted:null;if(n!=null){if(!Number.isInteger(n)||!Number.isInteger(k)||n<=0||k<0||k>n)return null;return{record,observed:k/n,estimate:(k+.5)/(n+1),interval:wilson(k,n),applicants:n,admitted:k,method:'Jeffreys-smoothed cohort estimate; Wilson interval for the observed cohort rate'}}if(typeof v==='number'&&v>=0&&v<=100)return{record,observed:v/100,estimate:v/100,interval:null,applicants:null,admitted:null,method:'Published rounded cohort rate; sample size not provided'};return null}
 function odds(p,factor=1){if(!(factor>0)||!Number.isFinite(factor))return p;if(p<=0)return 0;if(p>=1)return 1;return p*factor/(1-p+p*factor)}
 function select(input,metrics,custom=[]){const inst=college(input.institution),get=id=>metrics.find(m=>m.id===id);let campus=null,major=null,notes=[];if(inst==='UW Seattle'){if(input.route==='first-year')campus=get(input.residency==='wa'?'seattle-fy-7':input.residency==='nonwa'?'seattle-fy-8':'seattle-first-year-cohort');else if(input.route==='transfer')campus=get(input.origin==='wacc'?'seattle-transfer-14':input.origin==='other'?'seattle-transfer-15':'seattle-transfer-cohort');const cs=/^(?:Computer Science|Computer Engineering)\b/i.test(input.major||'');if(cs&&input.route==='first-year'&&['wa','nonwa'].includes(input.residency))major=get(input.residency==='wa'?'seattle-fy-11':'seattle-fy-12');else if(cs&&input.route==='transfer'&&['wa','nonwa'].includes(input.residency)&&['wacc','other'].includes(input.origin)){const map={wacc:{wa:16,nonwa:17},other:{wa:18,nonwa:19}};major=get('allen-2025-'+map[input.origin][input.residency]);}else if(/engineering/i.test(input.major||'')&&input.route==='first-year'&&['wa','nonwa'].includes(input.residency)){major=get(input.residency==='wa'?'seattle-fy-9':'seattle-fy-10');notes.push('Engineering Direct to College is not admission to a specific engineering major.');}}else if(inst==='UW Bothell'){if(input.route==='first-year')campus=get('bothell-first-year-cohort');if(input.route==='transfer')campus=get('bothell-transfer-cohort');notes.push('This campus dataset is not stratified by residency or major.');}const entered=custom.filter(r=>r.institution===inst&&r.route===input.route&&(!r.residency||r.residency==='unknown'||r.residency===input.residency)&&(!r.origin||r.origin==='unknown'||r.origin===input.origin)&&(r.programId&&r.programId===input.programId||!r.programId&&r.program===input.major));if(entered.length)major=entered.at(-1);if(!major)notes.push('A college rate is not substituted for a missing major rate. Add a matching published major cohort if one is available.');if(input.route==='current-student')notes.push('College-entry cohorts do not describe current-student major admission.');return{campus:evidence(campus),major:evidence(major),notes}}
 function scenario(result,factor=1){if(!result)return null;return{...result,scenario:odds(result.estimate,factor),sensitivity:[odds(result.estimate,.5),odds(result.estimate,2)],factor,individualModelValidated:false}}
 function format(p){if(p==null)return 'No matched cohort';if(p>0&&p<.01)return '<1%';if(p>.99&&p<1)return '>99%';return Math.round(p*100)+'%'}
 return{college,wilson,evidence,odds,select,scenario,format};
})();if(typeof module!=='undefined')module.exports=AdmissionsEstimator;
